def magic_square_test(square):
  n = len(square)
  magic_square = True
  for i in range(n):
    if sum(square[i]) != n * (n * n + 1) / 2:
      magic_square = False
      break
    if sum([square[j][i] for j in range(n)]) != n * (n * n + 1) / 2:
      magic_square = False
      break
  if n * (n * n + 1) / 2 != sum([sum(row) for row in square]):
    magic_square = False
  return magic_square
```

