def reverse_vowels(s):
  vowels = "aeiouAEIOU"
  s = list(s)
  i = 0
  j = len(s) - 1
  while i < j:
    if s[i] not in vowels:
      i += 1
    elif s[j] not in vowels:
      j -= 1
    else:
      s[i], s[j] = s[j], s[i]
      i += 1
      j -= 1
  return ''.join(s)
